import java.util.Map;

import lombok.Data;
import lombok.EqualsAndHashCode;
import lombok.experimental.Accessors;
import cn.hutool.core.lang.Assert;

/**
 * table output
 */
@Data
@Accessors(chain = true)
@EqualsAndHashCode(callSuper = true)
public class TableOutput extends Table<TableOutput> implements StepData {

    private final StepType type = StepType.TABLE_OUTPUT;

    private String id;

    private String label;

    private String name;

    // 事件时间 (字段名)
    private String eventTimeColumn;

    // 字典标识 (字段名)
    private String dictColumn;

    // 操作类型 (merge, update ?)
    private String operateType;

    // 字段映射
    private List<ColPair> mapping = new ArrayList<>();

    public TableOutput addMapping(ColPair pair) {
        Assert.notNull(pair, "pair cannot be null");
        Assert.notNull(pair.getSource(), "pair.source cannot be empty");
        Assert.notNull(pair.getTarget(), "pair.target cannot be empty");
        mapping.add(pair);
        return this;
    }

    @Override
    public String toString() {
        return DfUtil.toJson(this);
    }

    @Override
    public void check(Map<String, Object> variable) {
        super.check(variable);
        Assert.notEmpty(mapping, "mapping cannot be empty");
        for (ColPair pair : mapping) {
            pair.check(variable);
        }
    }

}

